// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzzed params: from address (as uint160), a single-to recipient index selection, and an amount
    function testFuzz_property(uint160 fromAddr, uint256 amount, bool calleeShouldRevert) public {
        // Keep addresses wide but non-zero
        address from = address(fromAddr == 0 ? 1 : fromAddr);
        // Ensure we have at least one recipient: construct a single-element array for clarity
        address[] memory tos = new address[](1);
        // Deploy a helper callee whose behavior we control
        ReverterOrRecorder helper = new ReverterOrRecorder();
        // set whether helper will revert when called
        helper.setShouldRevert(calleeShouldRevert);
        tos[0] = address(helper);
        uint[] memory vals = new uint[](1);
        // bound amount to a reasonable uint to avoid overflow in crazier setups
        vals[0] = uint256(bound(amount, 0, type(uint256).max));

        // The rule: reference C reverts the whole transfer() if the external call reverts.
        // So we call and observe whether it reverts.
        bool ok;
        try c.transfer(from, address(helper), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the helper is set to revert on its transferFrom call, the reference contract MUST revert
        // (because it checks the success flag and reverts when the call failed). The mutant that
        // removes the revert will instead return true (not revert) for that input. Therefore we assert
        // that when the helper will revert the call, c.transfer did revert (ok == false).
        // This is a universal property over all admissible inputs: for any inputs with non-empty tos
        // and a callee that reverts, the correct contract reverts; the mutant fails to do so for some inputs.
        if (calleeShouldRevert) {
            assertTrue(!ok);
        } else {
            // when helper does NOT revert, both reference and mutant succeed; ensure it indeed succeeded
            assertTrue(ok);
        }
    }
}

// Adversarial helper that can be toggled to revert (to exercise the external call failure)
contract ReverterOrRecorder {
    bool public shouldRevert;
    // records last received args for observation if needed
    address public lastFrom;
    address public lastTo;
    uint public lastValue;

    // signature must match: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        if (shouldRevert) {
            revert("reverting as configured");
        }
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        return true;
    }

    function setShouldRevert(bool r) external {
        shouldRevert = r;
    }

    // fallback to catch low-level calls too (not strictly necessary here)
    fallback() external payable {
        if (shouldRevert) revert("fallback revert");
    }
    receive() external payable {}
}
